1	/**
2	 * pysort.mjs — `sorted()` over Python strings.
3	 *
4	 * `str.__lt__` compares code points. JS's `<` compares UTF-16 code units, and
5	 * the two disagree for every astral character: U+1F600 encodes as D83D DE00, so
6	 * JS ranks it *below* U+E000..U+FFFF while Python ranks it above. The reference
7	 * executable confirms Python's order:
8	 *
9	 *   --a $'\xf0\x9f\x98\x80' --b $'\xef\xbf\xbd'
10	 *     -> b'["\xef\xbf\xbd","\xf0\x9f\x98\x80"]'   (U+FFFD sorts first)
11	 *
12	 * so the comparison below walks code points explicitly.
13	 */
14	
15	/** `(a > b) - (a < b)` for Python `str`, comparing code point by code point. */
16	export function compareCodePoints(a, b) {
17	  const ia = a[Symbol.iterator]();
18	  const ib = b[Symbol.iterator]();
19	
20	  for (;;) {
21	    const na = ia.next();
22	    const nb = ib.next();
23	    if (na.done) return nb.done ? 0 : -1; // a is a proper prefix of b
24	    if (nb.done) return 1;
25	    const ca = na.value.codePointAt(0);
26	    const cb = nb.value.codePointAt(0);
27	    if (ca !== cb) return ca < cb ? -1 : 1;
28	  }
29	}
30	
31	/**
32	 * `sorted(iterable)` for a sequence of strings.
33	 *
34	 * Returns a new array; the input is left untouched, matching `sorted()` rather
35	 * than `list.sort()`. `Array.prototype.sort` is stable in every supported V8,
36	 * which lines up with Python's Timsort for equal elements.
37	 */
38	export function pySorted(items) {
39	  return Array.from(items).sort(compareCodePoints);
40	}
