1	/**
2	 * pynumber.mjs — Python's `repr()` for the numeric types `json` can emit.
3	 *
4	 * `json` serialises numbers with `int.__repr__` and `float.__repr__`, and
5	 * `float.__repr__` differs from JS's `String(x)` in two visible ways: the
6	 * threshold at which it switches to exponent form, and the zero-padded
7	 * two-digit exponent. Only strings reach the encoder from `test7.py`, but the
8	 * library is written to be correct for the whole JSON type domain.
9	 */
10	
11	import { PyValueError } from './pyerrors.mjs';
12	
13	/**
14	 * Marks a value that must serialise as a Python `float` even when it happens to
15	 * hold an integral value — JS cannot distinguish `1` from `1.0` on its own.
16	 *
17	 *   encodeCanonicalJson(new PyFloat(1)) -> b'1.0'
18	 */
19	export class PyFloat {
20	  constructor(value) {
21	    this.value = Number(value);
22	  }
23	}
24	
25	/** `int.__repr__` — exact for `BigInt` and for any integral `Number`. */
26	export function pyIntRepr(value) {
27	  if (typeof value === 'bigint') return value.toString();
28	  return BigInt(value).toString();
29	}
30	
31	/**
32	 * `float.__repr__`.
33	 *
34	 * CPython asks for the shortest round-tripping digit string, then chooses a
35	 * layout from the decimal point position `decpt` (the value equals
36	 * `0.<digits> * 10**decpt`): exponent form when `decpt <= -4 || decpt > 16`,
37	 * fixed form otherwise, always with at least one fractional digit.
38	 */
39	export function pyFloatRepr(value) {
40	  const x = Number(value);
41	  if (Number.isNaN(x)) return 'nan';
42	  if (x === Infinity) return 'inf';
43	  if (x === -Infinity) return '-inf';
44	
45	  const negative = x < 0 || Object.is(x, -0);
46	  const magnitude = Math.abs(x);
47	  if (magnitude === 0) return negative ? '-0.0' : '0.0';
48	
49	  // `toExponential()` with no argument yields the shortest digit string that
50	  // uniquely identifies the double — the same guarantee CPython relies on.
51	  const parsed = /^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(magnitude.toExponential());
52	  const digits = parsed[1] + (parsed[2] || '');
53	  const decpt = parseInt(parsed[3], 10) + 1;
54	
55	  let text;
56	  if (decpt <= -4 || decpt > 16) {
57	    const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
58	    const exponent = decpt - 1;
59	    const sign = exponent < 0 ? '-' : '+';
60	    text = `${mantissa}e${sign}${String(Math.abs(exponent)).padStart(2, '0')}`;
61	  } else if (decpt <= 0) {
62	    text = `0.${'0'.repeat(-decpt)}${digits}`;
63	  } else if (decpt >= digits.length) {
64	    text = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
65	  } else {
66	    text = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
67	  }
68	
69	  return negative ? `-${text}` : text;
70	}
71	
72	/**
73	 * Serialises a number the way `json.JSONEncoder(allow_nan=False)` does.
74	 * canonicaljson passes `allow_nan=False`, so the non-finite values raise
75	 * instead of producing the `NaN`/`Infinity` JSON extensions.
76	 */
77	export function jsonNumberRepr(value) {
78	  if (value instanceof PyFloat) {
79	    assertFinite(value.value);
80	    return pyFloatRepr(value.value);
81	  }
82	  if (typeof value === 'bigint') return pyIntRepr(value);
83	  assertFinite(value);
84	  return Number.isInteger(value) ? pyIntRepr(value) : pyFloatRepr(value);
85	}
86	
87	function assertFinite(x) {
88	  if (!Number.isFinite(Number(x))) {
89	    throw new PyValueError('Out of range float values are not JSON compliant');
90	  }
91	}
