1	/**
2	 * pybytes.mjs — a `bytes` value plus CPython's `repr()` for it.
3	 *
4	 * `encode_canonical_json` returns `bytes`, and `print()` of a `bytes` object
5	 * emits its repr. Getting that repr byte-exact is most of the observable output
6	 * of this program, so the rules are spelled out below.
7	 */
8	
9	/**
10	 * CPython's `bytes_repr`:
11	 *
12	 *   * The quote character is `'`, unless the value contains `'` and no `"`, in
13	 *     which case `"` is used instead.
14	 *   * `\\` for a backslash, and `\` + quote for the active quote character. The
15	 *     *inactive* quote character is emitted raw.
16	 *   * `\t`, `\n`, `\r` for 0x09, 0x0a, 0x0d.
17	 *   * `\xNN` (lowercase hex) for any other byte below 0x20 or at/above 0x7f.
18	 *   * Everything else is emitted as its ASCII character.
19	 */
20	export function bytesRepr(bytes) {
21	  const buf = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
22	
23	  let hasSingle = false;
24	  let hasDouble = false;
25	  for (const b of buf) {
26	    if (b === 0x27) hasSingle = true;
27	    else if (b === 0x22) hasDouble = true;
28	  }
29	  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
30	  const quoteChar = String.fromCharCode(quote);
31	
32	  let body = '';
33	  for (const b of buf) {
34	    if (b === quote || b === 0x5c) {
35	      body += '\\' + String.fromCharCode(b);
36	    } else if (b === 0x09) {
37	      body += '\\t';
38	    } else if (b === 0x0a) {
39	      body += '\\n';
40	    } else if (b === 0x0d) {
41	      body += '\\r';
42	    } else if (b < 0x20 || b >= 0x7f) {
43	      body += '\\x' + b.toString(16).padStart(2, '0');
44	    } else {
45	      body += String.fromCharCode(b);
46	    }
47	  }
48	
49	  return 'b' + quoteChar + body + quoteChar;
50	}
51	
52	/**
53	 * Thin `bytes` wrapper. It exists so `pyPrint` can tell a `bytes` result apart
54	 * from a `str` without guessing, mirroring how the Python source relies on
55	 * `print(b'...')` dispatching to `bytes.__repr__`.
56	 */
57	export class PyBytes {
58	  constructor(bytes) {
59	    this.bytes = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
60	  }
61	
62	  static from(bytes) {
63	    return new PyBytes(bytes);
64	  }
65	
66	  /** `len(b)` */
67	  get length() {
68	    return this.bytes.length;
69	  }
70	
71	  /** `repr(b)` */
72	  repr() {
73	    return bytesRepr(this.bytes);
74	  }
75	
76	  toString() {
77	    return this.repr();
78	  }
79	}
