import { runSuite } from './harness.mjs';

// Every ASCII byte 0x01..0x7f as the sole content of --a (NUL impossible in argv).
const cases = [];
for (let b = 1; b <= 0x7f; b += 1) {
  cases.push({ argv: ['--a', Buffer.from([b]), '--b', 'Z'], label: `byte 0x${b.toString(16)}` });
}
process.exit(runSuite('ascii-escapes', cases) ? 1 : 0);

import { runSuite } from './harness.mjs';

// Interesting code points, delivered as valid UTF-8.
const cps = [
  0x7f, 0x80, 0x85, 0xa0, 0xad, 0xff, 0x100, 0x2028, 0x2029, 0x200b, 0x2villa = 0,
];

import { runSuite } from './harness.mjs';

// Interesting non-ASCII code points, delivered as valid UTF-8.
const cps = [
  0x7f, 0x80, 0x85, 0x9f, 0xa0, 0xad, 0xff, 0x100, 0x37e,
  0x200b, 0x2028, 0x2029, 0x2000, 0xd7ff, 0xe000, 0xfeff, 0xfffd, 0xffff,
  0x10000, 0x1f600, 0x10ffff, 0xe0001, 0x1d160,
];
const cases = [];
for (const cp of cps) {
  const s = String.fromCodePoint(cp);
  cases.push({ argv: ['--a', s, '--b', 'Z'], label: `U+${cp.toString(16)}` });
  cases.push({ argv: ['--a', 'x' + s + 'y', '--b', s + s], label: `U+${cp.toString(16)} embedded` });
}
// Sorting interactions: astral vs BMP, prefixes, equal strings
const pairs = [
  ['\u{1f600}', '�'],
  ['', '\u{10000}'],
  ['a', 'a'],
  ['ab', 'a'],
  ['', ''],
  ['', 'a'],
  ['é', 'é'],
  ['Z', 'a'],
  ['[', '\\'],
  ['"', "'"],
  ['\t', '\n'],
  ['�'.replace('�', ''), ''],
];
for (const [a, b] of pairs) cases.push({ argv: ['--a', a, '--b', b], label: `pair ${JSON.stringify([a, b])}` });

process.exit(runSuite('codepoints', cases) ? 1 : 0);

import { runSuite } from './harness.mjs';

const cases = [];
// A single invalid byte at every position 0..3 of a short string, and in --b.
for (const bad of [0x80, 0xbf, 0xc0, 0xc1, 0xed, 0xf5, 0xfe, 0xff, 0xf4, 0xe0]) {
  cases.push({ argv: ['--a', Buffer.from([bad]), '--b', 'Z'], label: `a=<${bad.toString(16)}>` });
  cases.push({ argv: ['--a', 'Z', '--b', Buffer.from([bad])], label: `b=<${bad.toString(16)}>` });
  cases.push({
    argv: ['--a', Buffer.concat([Buffer.from('ab'), Buffer.from([bad]), Buffer.from('cd')]), '--b', 'Z'],
    label: `a=ab<${bad.toString(16)}>cd`,
  });
}
// Runs of invalid bytes (grouped error ranges) and escapes that shift the offset.
cases.push({ argv: ['--a', Buffer.from([0xff, 0xfe]), '--b', 'Z'], label: 'run of 2' });
cases.push({ argv: ['--a', Buffer.from([0xff, 0xfe, 0xfd, 0xfc]), '--b', 'Z'], label: 'run of 4' });
cases.push({ argv: ['--a', Buffer.from([0xff, 0x41, 0xfe]), '--b', 'Z'], label: 'split run' });
// escape sequences before the bad byte -> JSON text is longer than input
cases.push({
  argv: ['--a', Buffer.concat([Buffer.from('\t\n\\"'), Buffer.from([0xff])]), '--b', 'Z'],
  label: 'escapes then bad',
});
cases.push({
  argv: ['--a', Buffer.concat([Buffer.from('\x01\x02'), Buffer.from([0xff])]), '--b', 'Z'],
  label: 'u00xx then bad',
});
// bad byte only in --b, with escapes in --a shifting the position
cases.push({
  argv: ['--a', '', '--b', Buffer.from([0xff])],
  label: 'a escapes, b bad',
});
// astral char before the bad byte: code point index vs utf16 index
cases.push({
  argv: ['--a', Buffer.concat([Buffer.from('\u{1f600}\u{1f600}'), Buffer.from([0xff])]), '--b', 'Z'],
  label: 'astral then bad',
});
// overlong / truncated sequences
cases.push({ argv: ['--a', Buffer.from([0xe0, 0x80, 0x80]), '--b', 'Z'], label: 'overlong 3' });
cases.push({ argv: ['--a', Buffer.from([0xed, 0xa0, 0x80]), '--b', 'Z'], label: 'utf8 surrogate' });
cases.push({ argv: ['--a', Buffer.from([0xf4, 0x90, 0x80, 0x80]), '--b', 'Z'], label: 'above 10ffff' });
cases.push({ argv: ['--a', Buffer.from([0xe2, 0x82]), '--b', 'Z'], label: 'truncated 3' });
cases.push({ argv: ['--a', Buffer.from([0xf0, 0x9f, 0x98]), '--b', 'Z'], label: 'truncated 4' });
cases.push({ argv: ['--a', Buffer.from([0xc2]), '--b', 'Z'], label: 'truncated 2' });

process.exit(runSuite('surrogateescape', cases) ? 1 : 0);

import { runSuite } from './harness.mjs';

const cases = [];
// Bad bytes in both arguments (position must be reported for the FIRST one only).
cases.push({ argv: ['--a', Buffer.from('78ff', 'hex'), '--b', Buffer.from('ff79', 'hex')], label: 'both bad' });
cases.push({ argv: ['--a', Buffer.from('ff', 'hex'), '--b', Buffer.from('ff', 'hex')], label: 'both bad 2' });
// Bad run at the very end of --a (must not group across the '","' separator).
cases.push({ argv: ['--a', Buffer.from('61ffff', 'hex'), '--b', Buffer.from('ffff62', 'hex')], label: 'runs both sides' });

// Fuzz: random mixes of escapable ASCII, astral chars, and raw bad bytes.
function rng(seed) {
  let s = seed >>> 0;
  return () => ((s = (s * 1103515245 + 12345) >>> 0) / 4294967296);
}
const r = rng(0xc0ffee);
const alphabet = [];
for (let b = 1; b <= 0x2f; b += 1) alphabet.push(Buffer.from([b]));
for (const s of ['"', '\\', '/', 'a', 'Z', '', 'é', '€', '\u{1f600}', '\u{10ffff}', '�', ' ']) {
  alphabet.push(Buffer.from(s, 'utf8'));
}
for (const b of [0x80, 0xc0, 0xed, 0xf5, 0xff]) alphabet.push(Buffer.from([b]));

function randStr(n) {
  const parts = [];
  for (let i = 0; i < n; i += 1) parts.push(alphabet[Math.floor(r() * alphabet.length)]);
  return Buffer.concat(parts);
}
for (let i = 0; i < 220; i += 1) {
  const a = randStr(1 + Math.floor(r() * 7));
  const b = randStr(1 + Math.floor(r() * 7));
  cases.push({ argv: ['--a', a, '--b', b], label: `fuzz ${i}: ${a.toString('hex')} / ${b.toString('hex')}` });
}
process.exit(runSuite('fuzz-mixed', cases) ? 1 : 0);

