show('Date', () => encodeJsonValue(new Date(0)));
show('Uint8Array', () => encodeJsonValue(new Uint8Array([1, 2, 3])));
show('Set', () => encodeJsonValue(new Set([1, 2])));
show('PyBytes', () => encodeJsonValue(new PyBytes([65])));
show('class instance', () => encodeJsonValue(new (class Foo { constructor() { this.z = 1; } })()));
